document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("course-enrollment-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("coursePrice").value),t=parseFloat(document.getElementById("courseDuration").value),i=document.getElementById("courseQuality").value,r=document.getElementById("courseNiche").value,o=document.getElementById("instructorExperience").value,a=document.getElementById("existingAudience").value,d=document.getElementById("industryCredibility").value,s=parseFloat(document.getElementById("marketingBudget").value)||0,l=document.getElementById("marketingChannels").value,c=document.getElementById("launchStrategy").value,u=document.getElementById("marketDemand").value,m=document.getElementById("competitionLevel").value,g=parseInt(document.getElementById("projectionMonths").value),p={basic:.6,good:1,premium:1.4,exceptional:1.8},v={business:1.2,tech:1.4,marketing:1.3,design:1,personal:1.1,health:.9,finance:1.3,language:.8,music:.7,academic:.6},b={beginner:.5,intermediate:1,experienced:1.5,expert:2.2},h={none:.3,small:1,medium:2.5,large:4},$={building:.8,recognized:1,established:1.4,renowned:1.8},y={organic:.7,social:1,paid:1.5,email:1.2,partnerships:1.3,marketplace:.9},f={soft:.6,standard:1,intensive:1.8,evergreen:.8},x={low:.5,medium:1,high:1.4,trending:1.8},F={low:1.4,medium:1,high:.7,saturated:.4};let E=1;E=n<50?1.3:n<=100?1.4:n<=200?1.2:n<=500?1:.6;let I=1;s>0&&(I=1+Math.min(s/1e3*.5,1));const M=p[i]*v[r]*b[o]*h[a]*$[d]*y[l]*f[c]*x[u]*F[m]*E*I;let k=Math.round(25*M),B=0,S=0;const w=[];for(let e=1;e<=g;e++){let t=1;t=e<=3?1.3:e<=6?1.1:e<=12?1:.9;const i=Math.round(k*t),r=i*n;B+=i,S+=r,w.push({month:e,enrollments:i,revenue:r}),k=.95*i}let C=.25;"premium"===i?C=.35:"exceptional"===i?C=.45:"basic"===i&&(C=.15),t<=2?C+=.1:t>=10&&(C-=.1);const L=S/g,z=1.2*n,O=Math.round(B*C),T=B/{business:5e5,tech:8e5,marketing:3e5,design:2e5,personal:4e5,health:3e5,finance:25e4,language:15e4,music:1e5,academic:2e5}[r]*100;let G="",A="";B>=5e3?(G="🚀 Exceptional Success",A="success"):B>=1e3?(G="✅ Strong Performance",A="success"):B>=200?(G="📈 Good Growth",A="info"):(G="🌱 Building Foundation",A="warning");document.getElementById("course-enrollment-result").innerHTML=`\n      <h3>🎓 Course Enrollment Forecast</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card ${A}">\n          <h6>👥 Total Students (${g}M)</h6>\n          <div class="big-number">${B.toLocaleString()}</div>\n          <p>${G}<br>\n          Avg: ${Math.round(B/g)} students/month<br>\n          Completion: ${Math.round(O).toLocaleString()} (${(100*C).toFixed(1)}%)</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>💰 Revenue Projection</h6>\n          <div class="big-number">$${Math.round(S).toLocaleString()}</div>\n          <p>Total over ${g} months<br>\n          Monthly avg: $${Math.round(L).toLocaleString()}<br>\n          Student LTV: $${Math.round(z).toLocaleString()}</p>\n        </div>\n        \n        <div class="insight-card info">\n          <h6>📊 Market Impact</h6>\n          <div class="big-number">${T.toFixed(3)}%</div>\n          <p>Market penetration<br>\n          Course price: $${n}<br>\n          ${t}h of content</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📈 Growth Analysis & Strategy</h4>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 1rem;">\n          <div>\n            <strong>🎯 Success Factors:</strong><br>\n            Course quality: ${i} (${(100*p[i]).toFixed(0)}%)<br>\n            Niche appeal: ${r} (${(100*v[r]).toFixed(0)}%)<br>\n            Instructor exp: ${o} (${(100*b[o]).toFixed(0)}%)<br>\n            Audience size: ${a} (${(100*h[a]).toFixed(0)}%)<br>\n            Credibility: ${d} (${(100*$[d]).toFixed(0)}%)<br>\n            Market demand: ${u} (${(100*x[u]).toFixed(0)}%)\n          </div>\n          \n          <div>\n            <strong>📊 Strategy Impact:</strong><br>\n            Marketing channel: ${l} (${(100*y[l]).toFixed(0)}%)<br>\n            Launch strategy: ${c} (${(100*f[c]).toFixed(0)}%)<br>\n            Competition level: ${m} (${(100*F[m]).toFixed(0)}%)<br>\n            Price optimization: $${n} (${(100*E).toFixed(0)}%)<br>\n            Marketing budget: $${s}/month (${(100*I).toFixed(0)}%)<br>\n            Overall multiplier: ${M.toFixed(2)}x\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; padding: 1rem; background: white; border-radius: 8px;">\n          <strong>📅 Monthly Enrollment Timeline:</strong><br>\n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 0.5rem; margin-top: 0.5rem; font-size: 0.9em;">\n            ${w.slice(0,12).map(e=>`\n              <div style="text-align: center; padding: 0.5rem; background: #f8f9fa; border-radius: 4px;">\n                Month ${e.month}<br>\n                <strong>${e.enrollments}</strong> students<br>\n                <small>$${(e.revenue/1e3).toFixed(0)}K</small>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${B>=1e3?"#d4edda":B>=200?"#fff3cd":"#f8d7da"}; border-radius: 8px; border-left: 4px solid ${B>=1e3?"#28a745":B>=200?"#ffc107":"#dc3545"};">\n          <strong>💡 Success Strategy Recommendations:</strong><br>\n          ${B>=1e3?"🎉 Excellent forecast! Focus on student success and retention, consider advanced courses and coaching upsells. Build community around your expertise.":B>=200?"✅ Solid potential! Optimize completion rates, gather testimonials, and plan follow-up courses. Invest in email marketing and community building.":"📈 Building phase. Focus on course quality, student outcomes, and organic marketing. Consider lowering price initially to build reviews and testimonials."}<br><br>\n          \n          <strong>🚀 Growth Optimization Tips:</strong><br>\n          • ${C<.3?"Improve course structure and engagement to boost completion rates":"Excellent completion rate - leverage for testimonials and referrals"}<br>\n          • ${s<300?"Consider increasing marketing budget for faster growth":"Optimize current marketing spend for better ROI"}<br>\n          • ${M<1?"Focus on building credibility and audience before launch":"Strong positioning - maintain quality and consistency"}<br>\n          • ${n<100?"Consider price testing - may be undervaluing your expertise":n>500?"High price point - ensure exceptional value delivery":"Good price positioning for market"}\n        </div>\n      </div>\n    `})});